from itertools import combinations, product
import sys

def search(naux, maxk, signed=False):
    nv = 3 + naux
    # build clauses: tuples of (var, sign) with distinct vars
    clauses = []
    for combo in combinations(range(nv), 3):
        opts = []
        for v in combo:
            if signed or v >= 3:
                opts.append([(v,1),(v,-1)])
            else:
                opts.append([(v,1)])
        for choice in product(*opts):
            clauses.append(tuple(sorted(choice)))
    clauses = sorted(set(clauses))
    nc = len(clauses)
    # precompute M[c][i] bitmask over aux assignments
    M = [[0]*8 for _ in range(nc)]
    for ci, cl in enumerate(clauses):
        for i in range(8):
            inp = [(i>>0)&1, (i>>1)&1, (i>>2)&1]
            mask = 0
            for j in range(1<<naux):
                aux = [(j>>b)&1 for b in range(naux)]
                assign = inp + aux
                def lv(l):
                    v,s = l
                    return assign[v] if s==1 else 1-assign[v]
                if sum(lv(l) for l in cl) == 1:
                    mask |= (1<<j)
            M[ci][i] = mask
    # all-false input i=0 must be unsat: AND over clauses of M[ci][0] == 0
    for k in range(1, maxk+1):
        for sub in combinations(range(nc), k):
            # quick check all-false
            m0 = (1<<(1<<naux)) - 1
            for ci in sub:
                m0 &= M[ci][0]
                if m0 == 0: break
            if m0 != 0:
                continue
            good = True
            for i in range(1,8):
                m = (1<<(1<<naux)) - 1
                for ci in sub:
                    m &= M[ci][i]
                    if m == 0:
                        good = False; break
                if not good: break
            if good:
                return [clauses[ci] for ci in sub]
        print("  k",k,"done", flush=True)
    return None

for signed in (False, True):
    for naux in (1,2,3):
        print("signed",signed,"naux",naux, flush=True)
        r = search(naux, 8 if naux<=2 else 6, signed)
        print("  RESULT", r, flush=True)
        if r: sys.exit()
